def rep(old,new,label,count=1):
    global s
    if old not in s:
        raise SystemExit(f'v1.4 patch failed: {label}')
    s=s.replace(old,new,count)

def rrep(pattern,new,label):
    global s
    ns,n=re.subn(pattern,new,s,count=1,flags=re.S)
    if n!=1:
        raise SystemExit(f'v1.4 patch failed: {label} ({n})')
    s=ns

