# Add CSRF-aware POST support to the native API client so community points can be registered.
a=JAVA/'NativeApiClient.java'
t=a.read_text()
old='''    Response get(String base,String path) throws Exception {return request(base,path,"GET",null,25000,16*1024*1024);}\n    Response getLarge(String base,String path) throws Exception {return request(base,path,"GET",null,90000,70*1024*1024);}\n    Response post(String base,String path,JSONObject data) throws Exception {return request(base,path,"POST",data==null?"{}":data.toString(),30000,8*1024*1024);}\n\n    private Response request(String base,String path,String method,String json,int timeout,int maxBytes) throws Exception {'''
new='''    Response get(String base,String path) throws Exception {return request(base,path,"GET",null,25000,16*1024*1024,null);}\n    Response getLarge(String base,String path) throws Exception {return request(base,path,"GET",null,90000,70*1024*1024,null);}\n    Response post(String base,String path,JSONObject data) throws Exception {return request(base,path,"POST",data==null?"{}":data.toString(),30000,8*1024*1024,null);}\n    Response postCsrf(String base,String path,JSONObject data,String csrf) throws Exception {return request(base,path,"POST",data==null?"{}":data.toString(),30000,8*1024*1024,csrf);}\n\n    private Response request(String base,String path,String method,String json,int timeout,int maxBytes,String csrf) throws Exception {'''
if old not in t: raise SystemExit('v1.4 patch failed: NativeApiClient methods')
t=t.replace(old,new,1)
old2='''        c.setRequestProperty("X-MusicRoad-Native","1");\n        c.setRequestProperty("User-Agent","MusicRoadAndroid/"+BuildConfig.VERSION_NAME+" NativeCore");'''
new2='''        c.setRequestProperty("X-MusicRoad-Native","1");\n        if(csrf!=null&&!csrf.trim().isEmpty())c.setRequestProperty("X-CSRF-Token",csrf.trim());\n        c.setRequestProperty("User-Agent","MusicRoadAndroid/"+BuildConfig.VERSION_NAME+" NativeCore");'''
if old2 not in t: raise SystemExit('v1.4 patch failed: NativeApiClient csrf header')
t=t.replace(old2,new2,1)
a.write_text(t)

